376	    @Transactional
377	    @Override
378	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
379	        Owner owner = this.clinicService.findOwnerById(ownerId);
380	        if (owner == null) {
381	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	        }
383	        this.clinicService.deleteOwner(owner);
384	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
385	    }
386	
387	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
388	    @Override
389	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
390	        Owner owner = this.clinicService.findOwnerById(ownerId);
391	        if (owner == null) {
392	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
393	        }
394	        HttpHeaders headers = new HttpHeaders();
395	        Pet pet = petMapper.toPet(petFieldsDto);
396	        owner.setId(ownerId);
397	        pet.setOwner(owner);
398	        pet.getType().setName(null);
399	        this.clinicService.savePet(pet);
400	        PetDto petDto = petMapper.toPetDto(pet);
401	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
402	            .buildAndExpand(pet.getId()).toUri());
403	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
404	    }
405	
406	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
407	    @Override
408	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
409	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
410	        if (currentOwner != null) {
411	            Pet currentPet = this.clinicService.findPetById(petId);
412	            if (currentPet != null) {
413	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
414	                currentPet.setName(petFieldsDto.getName());
415	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
416	                this.clinicService.savePet(currentPet);
417	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
418	            }
419	        }
420	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	    }
422	
423	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
424	    @Override
425	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
426	        HttpHeaders headers = new HttpHeaders();
427	        Visit visit = visitMapper.toVisit(visitFieldsDto);
428	        Pet pet = new Pet();
429	        pet.setId(petId);
430	        visit.setPet(pet);
431	        this.clinicService.saveVisit(visit);
432	        VisitDto visitDto = visitMapper.toVisitDto(visit);
433	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
434	            .buildAndExpand(visit.getId()).toUri());
435	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
436	    }
437	
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner != null) {
444	            Pet pet = owner.getPet(petId);
445	            if (pet != null) {
446	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
